#[test]
fn a_nul_glued_to_a_number_is_a_fault_at_the_nul_7966() -> Result<()> {
    for (input, stdout, exit, stderr) in ROWS {
        let (out, err, code) = run_jq_full(&["-c", "."], Some(input))?;
        assert_eq!(
            (out.as_str(), code, err.trim_end()),
            (*stdout, *exit, *stderr),
            "{input:?}"
        );
    }
    Ok(())
}

/// The routes that read the input, each over every eighth row as one file and on standard input:
/// the fault is the same message on each, worded as the route words a parse error. `--stream` hands
/// out the events before the NUL first (`[1,`, NUL is `[[0],1]`), so only its stderr and exit
/// status are held here. `-s` on standard
/// input and a program that reads only the input's type are left out: the first words any fault in
/// the splitter's own words, and the second does not read the bytes after the opener (#3035), for a
/// NUL as for any other fault.
#[test]
fn every_route_reports_the_nul_where_it_stands_7966() -> Result<()> {
    for (input, _, _, stderr) in ROWS.iter().step_by(8) {
        let message = stderr.trim_start_matches("jq: parse error: ");
        let file = format!("jq: error (at <file>:1): {message}");
        let stdin = format!("jq: error (at <stdin>:1): {message}");
        for (args, on_file, on_stdin) in [
            (&["-c", "."][..], *stderr, Some(*stderr)),
            (&["-cs", "."][..], *stderr, None),
            (
                &["-cn", "[inputs]"][..],
                file.as_str(),
                Some(stdin.as_str()),
            ),
            (&["-c", "--stream", "."][..], *stderr, Some(*stderr)),
        ] {
            let (out, err, code, name) = run_jq_over_byte_files(args, &[input.as_bytes()])?;
            let err = err.replace(&name[0], "<file>");
            let events = args.contains(&"--stream");
            assert_eq!(
                (events || out.is_empty(), code, err.trim_end()),
                (true, 5, on_file),
                "file {args:?} {input:?}"
            );
            if let Some(want) = on_stdin {
                let (out, err, code) = run_jq_full(args, Some(input))?;
                assert_eq!(
                    (events || out.is_empty(), code, err.trim_end()),
                    (true, 5, want),
                    "stdin {args:?} {input:?}"
                );
            }
        }
    }
    Ok(())
}

